 8	public static class LotEndpoints
 9	{
10	    private static object View(Lot l) => new
11	    {
12	        id = l.Id, label = l.Label, weight_kg = l.WeightKg, moisture_pct = l.MoisturePct,
13	        state = l.State, created_at = l.CreatedAt, updated_at = l.UpdatedAt,
14	    };
