16	    public static void MapLots(this IEndpointRouteBuilder app)
17	    {
18	        app.MapGet("/lots", async (string? state, HttpContext http, ApiaryDb db, CancellationToken ct) =>
19	        {
20	            if (state is not null && !LotLifecycle.IsState(state))
21	            {
22	                var bad = new Check();
23	                bad.Problems["state"] = "is not a lot state";
24	                return Failure.Invalid(bad);
25	            }
26	            var me = Caller.Of(http);
27	            var query = db.Lots.AsNoTracking().Where(l => l.OwnerId == me.Id);
28	            if (state is not null) query = query.Where(l => l.State == state);
29	            return Results.Json((await query.OrderBy(l => l.Id).ToListAsync(ct)).Select(View));
30	        }).RequireSignIn();
31	
32	        app.MapPost("/lots", async (LotBody body, HttpContext http, ApiaryDb db, CancellationToken ct) =>
33	        {
34	            var check = new Check();
35	            var label = check.Text("label", body.Label, 1, 60);
36	            var weight = check.Number("weight_kg", body.WeightKg, 0.1, 500);
37	            var moisture = check.Number("moisture_pct", body.MoisturePct, 10, 30);
38	            if (!check.Ok) return Failure.Invalid(check);
39	
40	            var now = DateTime.UtcNow;
41	            var lot = new Lot
42	            {
43	                OwnerId = Caller.Of(http).Id, Label = label!, WeightKg = weight, MoisturePct = moisture,
44	                State = LotLifecycle.Extracted, CreatedAt = now, UpdatedAt = now,
45	            };
46	            db.Lots.Add(lot);
47	            await db.SaveChangesAsync(ct);
48	            return Results.Json(View(lot), statusCode: 201);
49	        }).RequireSignIn();
50	
51	        app.MapGet("/lots/{id:int}", async (int id, HttpContext http, ApiaryDb db, CancellationToken ct) =>
52	        {
53	            var me = Caller.Of(http);
54	            var lot = await db.Lots.AsNoTracking().FirstOrDefaultAsync(l => l.Id == id && l.OwnerId == me.Id, ct);
55	            return lot is null ? Failure.NotFound("lot") : Results.Json(View(lot));
56	        }).RequireSignIn();
57	
58	        app.MapPost("/lots/{id:int}/advance", async (int id, AdvanceBody body, HttpContext http, ApiaryDb db, CancellationToken ct) =>
59	        {
60	            var me = Caller.Of(http);
61	            var check = new Check();
62	            if (body.To is null) check.Problems["to"] = "is required";
63	            else if (!LotLifecycle.IsState(body.To)) check.Problems["to"] = "is not a lot state";
64	            if (body.MoisturePct is { } m && (double.IsNaN(m) || m < 10 || m > 30)) check.Problems["moisture_pct"] = "must be between 10 and 30";
65	            if (!check.Ok) return Failure.Invalid(check);
66	
67	            var lot = await db.Lots.AsNoTracking().FirstOrDefaultAsync(l => l.Id == id && l.OwnerId == me.Id, ct);
68	            if (lot is null) return Failure.NotFound("lot");
69	
70	            var to = body.To!;
71	            if (!LotLifecycle.CanMove(lot.State, to))
72	                return Failure.Conflict($"a lot that is {lot.State} cannot become {to}");
73	            var moisture = body.MoisturePct ?? lot.MoisturePct;
74	            if (to == LotLifecycle.Bottled && moisture > LotLifecycle.MaxBottlingMoisture)
75	                return Failure.Conflict($"moisture {moisture} is above {LotLifecycle.MaxBottlingMoisture}; the honey is too wet to bottle");
76	
77	            // The state in the WHERE clause makes the move atomic when two requests race on one lot.
78	            var from = lot.State;
79	            var changed = await db.Lots.Where(l => l.Id == id && l.OwnerId == me.Id && l.State == from)
80	                .ExecuteUpdateAsync(s => s.SetProperty(l => l.State, to)
81	                    .SetProperty(l => l.MoisturePct, moisture).SetProperty(l => l.UpdatedAt, DateTime.UtcNow), ct);
82	            if (changed == 0) return Failure.Conflict("the lot changed meanwhile; read it again");
83	
84	            var fresh = await db.Lots.AsNoTracking().FirstAsync(l => l.Id == id, ct);
85	            return Results.Json(View(fresh));
86	        }).RequireSignIn();
87	    }
88	}
