 9	/// <summary>The signed-in person behind a request, put on the request by <see cref="Guard"/>.</summary>
10	public sealed record Caller(int Id, string Name, string Role)
11	{
12	    private const string Key = "apiary.caller";
13	
14	    public static Caller Of(HttpContext ctx) => (Caller)ctx.Items[Key]!;
15	
16	    public static void Set(HttpContext ctx, Caller c) => ctx.Items[Key] = c;
17	}
18	
19	public static class Guard
20	{
21	    public static readonly TimeSpan SessionLife = TimeSpan.FromHours(12);
22	
23	    /// <summary>Requires a valid bearer token; with <paramref name="role"/>, only people holding that role pass.</summary>
24	    public static RouteHandlerBuilder RequireSignIn(this RouteHandlerBuilder route, string? role = null) =>
25	        route.AddEndpointFilter(async (ctx, next) =>
26	        {
27	            var http = ctx.HttpContext;
28	            var header = http.Request.Headers.Authorization.ToString();
29	            const string prefix = "Bearer ";
30	            if (!header.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) || header.Length == prefix.Length)
31	                return Failure.Unauthorized("sign in first");
32	
33	            var token = header[prefix.Length..].Trim();
34	            var db = http.RequestServices.GetRequiredService<ApiaryDb>();
35	            var now = DateTime.UtcNow;
36	            var who = await db.Sessions.AsNoTracking()
37	                .Where(s => s.Token == token && s.ExpiresAt > now)
38	                .Join(db.Users, s => s.UserId, u => u.Id, (s, u) => new Caller(u.Id, u.Name, u.Role))
39	                .FirstOrDefaultAsync(http.RequestAborted);
40	            if (who is null) return Failure.Unauthorized("the token is not valid");
41	            if (role is not null && who.Role != role) return Failure.Forbidden($"only the {role} role may do this");
42	
43	            Caller.Set(http, who);
44	            return await next(ctx);
45	        });
46	
47	    public static string NewToken() => Convert.ToBase64String(RandomNumberGenerator.GetBytes(32))
48	        .Replace('+', '-').Replace('/', '_').TrimEnd('=');
49	
50	    public static bool SameSecret(string stored, string typed) =>
51	        CryptographicOperations.FixedTimeEquals(
52	            SHA256.HashData(Encoding.UTF8.GetBytes(stored)), SHA256.HashData(Encoding.UTF8.GetBytes(typed)));
53	}
