 3	/// <summary>Every refusal the service sends, in one shape: <c>{"error": code, "detail": text, "fields": {...}}</c>.</summary>
 4	public static class Failure
 5	{
 6	    private static IResult Make(int status, string code, string detail, object? fields = null) =>
 7	        Results.Json(new { error = code, detail, fields }, statusCode: status);
 8	
 9	    public static IResult Unauthorized(string detail) => Make(401, "unauthorized", detail);
10	    public static IResult Forbidden(string detail) => Make(403, "forbidden", detail);
11	    public static IResult NotFound(string what) => Make(404, "not_found", $"{what} not found");
12	    public static IResult Conflict(string detail) => Make(409, "conflict", detail);
13	    public static IResult Invalid(Check check) => Make(400, "invalid", "the request has missing or out-of-range values", check.Problems);
14	}
15	
16	/// <summary>Collects what is wrong with a request body; an empty set means the body is acceptable.</summary>
17	public sealed class Check
18	{
19	    public Dictionary<string, string> Problems { get; } = new();
20	
21	    public bool Ok => Problems.Count == 0;
22	
23	    public string? Text(string field, string? value, int min, int max)
24	    {
25	        if (value is null) { Problems[field] = "is required"; return null; }
26	        var t = value.Trim();
27	        if (t.Length < min || t.Length > max) Problems[field] = $"must be {min} to {max} characters";
28	        return t;
29	    }
30	
31	    public string? OptionalText(string field, string? value, int max)
32	    {
33	        if (value is null) return null;
34	        if (value.Length > max) Problems[field] = $"must be at most {max} characters";
35	        return value;
36	    }
37	
38	    public int Int(string field, int? value, int min, int max)
39	    {
40	        if (value is null) { Problems[field] = "is required"; return 0; }
41	        if (value < min || value > max) Problems[field] = $"must be between {min} and {max}";
42	        return value.Value;
43	    }
44	
45	    public double Number(string field, double? value, double min, double max)
46	    {
47	        if (value is null) { Problems[field] = "is required"; return 0; }
48	        if (double.IsNaN(value.Value) || value < min || value > max) Problems[field] = $"must be between {min} and {max}";
49	        return value.Value;
50	    }
51	}
